1	import { mask } from "../../checks/mask";
2	import type { Message } from "./compose";
3	import { discordUrl } from "./channel-input";
4	import { neverLeft, type SendResult } from "./outcome";
5	
6	/** Provider JSON is bounded and never copied into errors or logs. */
7	export async function smallJson(r: Response): Promise<Record<string, unknown> | null> {
8	  const reader = r.body?.getReader();
9	  if (!reader) return null;
10	  const chunks: Uint8Array[] = [];
11	  let size = 0;
12	  try {
13	    while (true) {
14	      const { done, value } = await reader.read();
15	      if (done) break;
16	      size += value.length;
17	      if (size > 64 * 1024) { await reader.cancel(); return null; }
18	      chunks.push(value);
19	    }
20	    const data: unknown = JSON.parse(Buffer.concat(chunks).toString("utf8"));
21	    return data && typeof data === "object" && !Array.isArray(data) ? data as Record<string, unknown> : null;
22	  } catch { return null; }
23	  finally { reader.releaseLock(); }
24	}
25	
26	const text = (m: Message) => mask([m.subject, "", ...m.lines].join("\n"));
27	/** Composer messages end with a blank line and their incident/status links. Keep that
28	 *  footer whole when Discord's single-embed limit requires shortening the evidence. */
29	function discordText(m: Message): string {
30	  const whole = text(m);
31	  if (whole.length <= 4096) return whole;
32	  const footer = mask(m.lines.slice(-3).join("\n"));
33	  const prefix = mask([m.subject, "", ...m.lines.slice(0, -3)].join("\n"));
34	  return `${prefix.slice(0, Math.max(0, 4096 - footer.length - 3))}\n…\n${footer}`;
35	}
36	const uncertain = (name: string): SendResult => ({ kind: "unknown", detail: `${name} didn't confirm acceptance.` });
37	
38	export async function sendSlack(token: string, channel: string, message: Message, thread: string | null, doFetch: typeof fetch = fetch): Promise<SendResult> {
39	  try {
40	    const r = await doFetch("https://slack.com/api/chat.postMessage", {
41	      method: "POST", redirect: "manual", signal: AbortSignal.timeout(10_000),
42	      headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
43	      body: JSON.stringify({ channel, text: text(message).replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;"), mrkdwn: false, parse: "none", unfurl_links: false,
44	        unfurl_media: false, ...(thread ? { thread_ts: thread } : {}) }),
45	    });
46	    if (r.status === 429) { await r.body?.cancel(); return { kind: "retry", detail: "Slack asked us to wait.", retryAfterSec: Number(r.headers.get("retry-after")) || 60 }; }
47	    const data = await smallJson(r);
48	    if (r.ok && data?.ok === true && typeof data.ts === "string" && /^\d+\.\d+$/.test(data.ts))
49	      return { kind: "sent", messageId: data.ts, redirected: false };
50	    // Slack's internal/fatal errors may have performed part of the operation. No blind retry.
51	    if (r.status >= 500 || !data || data.ok !== false || ["internal_error", "fatal_error"].includes(String(data.error))) return uncertain("Slack");
52	    return { kind: "rejected", code: r.status, detail: "Slack refused this message. Check the app's access to the selected channel." };
53	  } catch (e) {
54	    return neverLeft(e, "manual") ? { kind: "retry", detail: "The Slack request never left." } : uncertain("Slack");
55	  }
56	}
57	
58	export async function sendDiscord(url: string, message: Message, doFetch: typeof fetch = fetch): Promise<SendResult> {
59	  const u = discordUrl(url);
60	  if (!u) return { kind: "rejected", code: 400, detail: "The Discord webhook is invalid. Remove this channel and add it again." };
61	  u.searchParams.set("wait", "true");
62	  try {
63	    const r = await doFetch(u, {
64	      method: "POST", redirect: "manual", signal: AbortSignal.timeout(10_000),
65	      headers: { "content-type": "application/json" },
66	      // One message, no chunk sends that could succeed only halfway. Embeds allow the evidence
67	      // and links to fit together; mentions are disabled even in customer-supplied text.
68	      body: JSON.stringify({ embeds: [{ description: discordText(message) }], allowed_mentions: { parse: [] } }),
69	    });
70	    const data = await smallJson(r);
